/// A fresh scratch directory keeps each test's `wal.bin` and `snapshot.fsdb` isolated.
let private tempDataDir () =
    TestSupport.directory "persistence"

let private usersColumns =
    [ { Name = "id"
        Type = TInt false
        NumericDisplay = None
        Nullable = false
        Default = None
        AutoIncrement = true
        PrimaryKey = true
        Unique = false
        Generated = None
        Comment = ""
        Collation = None
        Charset = None
        ExpressionCollation = None
        Srid = None
        OnUpdateCurrentTimestamp = false }
      { Name = "name"
        Type = TVarchar 255
        NumericDisplay = None
        Nullable = false
        Default = None
        AutoIncrement = false
        PrimaryKey = false
        Unique = false
        Generated = None
        Comment = ""
        Collation = None
        Charset = None
        ExpressionCollation = None
        Srid = None
        OnUpdateCurrentTimestamp = false }
      { Name = "note"
        Type = TText
        NumericDisplay = None
        Nullable = true
        Default = None
        AutoIncrement = false
        PrimaryKey = false
        Unique = false
        Generated = None
        Comment = ""
        Collation = None
        Charset = None
        ExpressionCollation = None
        Srid = None
        OnUpdateCurrentTimestamp = false } ]

/// No PK/AUTO_INCREMENT/UNIQUE at all — unlike `usersColumns`, a row
/// replayed twice inserts twice instead of the second copy silently dying
/// on a uniqueness violation, so a duplicate-replay bug shows up as a
/// row-count difference.
let private tagColumns =
    [ { Name = "tag"
        Type = TVarchar 64
        NumericDisplay = None
        Nullable = false
        Default = None
        AutoIncrement = false
        PrimaryKey = false
        Unique = false
        Generated = None
        Comment = ""
        Collation = None
        Charset = None
        ExpressionCollation = None
        Srid = None
        OnUpdateCurrentTimestamp = false } ]

let private walPath dir = Path.Combine(dir, "wal.bin")
let private snapshotPath dir = Path.Combine(dir, "snapshot.fsdb")

let private mkCol (name: string) (typ: ColumnType) : ColumnDef =
    { Name = name
      Type = typ
      NumericDisplay = None
      Nullable = true
      Default = None
      AutoIncrement = false
      PrimaryKey = false
      Unique = false
      Generated = None
      Comment = ""
      Collation = None
      Charset = None
      ExpressionCollation = None
      Srid = None
      OnUpdateCurrentTimestamp = false }

let private writeLegacyColumn (w: Writer) (name: string) =
    w.WriteLenEncString name
    w.WriteByte 0x04uy
    w.WriteByte 0uy
    w.WriteByte 1uy
    w.WriteByte 0uy
    w.WriteByte 0uy
    w.WriteByte 0uy
    w.WriteByte 0uy
    w.WriteByte 0uy
    w.WriteByte 0uy
    w.WriteByte 0uy
    w.WriteByte 0uy

let private writeLegacyTable (w: Writer) (name: string) =
    w.WriteLenEncString name
    w.WriteLenEncString name
    w.WriteInt32LE 1
    writeLegacyColumn w "id"
    w.WriteInt32LE 0
    w.WriteInt32LE 0
    w.WriteByte 0uy
    w.WriteByte 0uy
    w.WriteInt64LE 0L
    w.WriteInt64LE 1L
    w.WriteInt32LE 0

let private legacySnapshot (table: string) =
    let payload = Writer()
    payload.WriteInt32LE 1
    payload.WriteLenEncString defaultDatabase
    payload.WriteInt32LE 1
    writeLegacyTable payload table
    let payload = payload.ToArray()
    let snapshot = Writer()
    snapshot.WriteBytes [| 0x46uy; 0x53uy; 0x4Euy; 0x31uy |]
    snapshot.WriteBytes payload
    snapshot.WriteInt64LE(int64 payload.Length)
    snapshot.WriteUInt32LE(crc32 payload)
    snapshot.ToArray()

let private taggedIndexSnapshot (database: string) =
    let payload = Writer()
    payload.WriteInt32LE 1
    payload.WriteLenEncString database
    payload.WriteInt32LE 0
    payload.WriteInt32LE 0
    let payload = payload.ToArray()
    let snapshot = Writer()
    snapshot.WriteBytes [| 0x46uy; 0x53uy; 0x4Euy; 0x41uy |]
    snapshot.WriteBytes payload
    snapshot.WriteInt64LE(int64 payload.Length)
    snapshot.WriteUInt32LE(crc32 payload)
    snapshot.ToArray()

let private columnCommentSnapshot (table: string) (comment: string) =
    let payload = Writer()
    payload.WriteInt32LE 1
    payload.WriteLenEncString defaultDatabase
    payload.WriteInt32LE 1
    payload.WriteLenEncString table
    payload.WriteLenEncString table
    payload.WriteInt32LE 1
    writeLegacyColumn payload "id"
    payload.WriteLenEncString comment
    payload.WriteInt32LE 0
    payload.WriteInt32LE 0
    payload.WriteByte 0uy
    payload.WriteByte 0uy
    payload.WriteInt64LE 0L
    payload.WriteInt64LE 1L
    payload.WriteInt32LE 0
    let payload = payload.ToArray()
    let snapshot = Writer()
    snapshot.WriteBytes [| 0x46uy; 0x53uy; 0x4Euy; 0x32uy |]
    snapshot.WriteBytes payload
    snapshot.WriteInt64LE(int64 payload.Length)
    snapshot.WriteUInt32LE(crc32 payload)
    snapshot.ToArray()

let private fsn1ColumnCommentSnapshot (table: string) (comment: string) =
    let bytes = columnCommentSnapshot table comment
    bytes.[3] <- byte '1'
    bytes

let private legacyCreateTableWalRecord (table: string) =
    let payload = Writer()
    payload.WriteByte 0x04uy
    payload.WriteLenEncString defaultDatabase
    payload.WriteByte 0x03uy
    payload.WriteLenEncString table
    payload.WriteInt32LE 1
    writeLegacyColumn payload "id"
    payload.WriteInt32LE 0
    payload.WriteInt32LE 0
    payload.WriteByte 0uy
    payload.WriteByte 0uy
    payload.WriteByte 0uy
    payload.WriteByte 0uy
    let payload = payload.ToArray()
    let record = Writer()
    record.WriteInt32LE payload.Length
    record.WriteUInt32LE(crc32 payload)
    record.WriteBytes payload
    record.ToArray()

let private legacyXaPreparedWalRecord () =
    let payload = Writer()
    payload.WriteByte 0x0Fuy
    payload.WriteUInt32LE 7u
    payload.WriteInt32LE 3
    payload.WriteBytes [| byte 'o'; byte 'l'; byte 'd' |]
    payload.WriteInt32LE 0
    payload.WriteByte 0uy
    payload.WriteInt32LE 0
    let payload = payload.ToArray()
    let record = Writer()
    record.WriteInt32LE payload.Length
    record.WriteUInt32LE(crc32 payload)
    record.WriteBytes payload
    record.ToArray()

let private v3CreateTableWalRecord (table: string) (tableComment: string option) =
    let payload = Writer()
    payload.WriteByte 0x0Auy
    payload.WriteLenEncString defaultDatabase
    payload.WriteByte 0x03uy
    payload.WriteLenEncString table
    payload.WriteInt32LE 1
    writeLegacyColumn payload "id"
    payload.WriteLenEncString "v3 column"
    payload.WriteInt32LE 0
    payload.WriteInt32LE 0
    payload.WriteByte 0uy
    payload.WriteByte 0uy
    payload.WriteByte 0uy
    payload.WriteByte 0uy
    tableComment |> Option.iter (fun comment -> payload.WriteByte 1uy; payload.WriteLenEncString comment)
    payload.WriteInt64LE 0L
    let payload = payload.ToArray()
    let record = Writer()
    record.WriteInt32LE payload.Length
    record.WriteUInt32LE(crc32 payload)
    record.WriteBytes payload
    record.ToArray()

let private legacyAlterIndexesWalRecord (table: string) (column: string) (addColumn: bool) =
    let payload = Writer()
    payload.WriteByte 0x14uy
    payload.WriteLenEncString defaultDatabase
    payload.WriteByte 0x05uy
    payload.WriteLenEncString table
    payload.WriteInt32LE(if addColumn then 3 else 2)

    if addColumn then
        payload.WriteByte 0x01uy
        writeLegacyColumn payload column
        payload.WriteLenEncString ""
        payload.WriteByte 0uy
        payload.WriteByte 0x01uy

    payload.WriteByte 0x07uy
    payload.WriteLenEncString "ix_literal"
    payload.WriteInt32LE 1
    payload.WriteLenEncString column
    payload.WriteByte 0uy
    payload.WriteByte 0uy
    payload.WriteByte 0x0Buy
    payload.WriteInt32LE 1
    payload.WriteLenEncString column
    payload.WriteInt64LE 0L
    let payload = payload.ToArray()
    let record = Writer()
    record.WriteInt32LE payload.Length
    record.WriteUInt32LE(crc32 payload)
    record.WriteBytes payload
    record.ToArray()

let private rowsOf (store: Store) (dbName: string) (table: string) : Value[] list =
    match scan store dbName table with
    | Ok(_, rows) -> List.ofSeq rows
    | Error e -> failtestf "scan failed: %A" e

let tests =
    testList
        "persistence"
        [ testCase "renamed foreign-key columns retain enforcement across schemas and recovery"
          <| fun _ ->
              for checkpoint in [ false; true ] do
                  let directory = tempDataDir()
                  let store = load directory
                  attach directory store
                  let mutable session = Fsdb.Session.create 1 store
                  let run sql =
                      let next, result = handle session sql
                      session <- next
                      result
                  for sql in
                      [ "CREATE TABLE parent(n INT PRIMARY KEY)"
                        "CREATE TABLE child(a INT,CONSTRAINT fk FOREIGN KEY(a) REFERENCES parent(n))"
                        "CREATE DATABASE related"
                        "CREATE TABLE related.other_child(a INT,CONSTRAINT ext FOREIGN KEY(a) REFERENCES fsdb.parent(n))"
                        "INSERT INTO parent VALUES(1)"
                        "INSERT INTO child VALUES(1)"
                        "INSERT INTO related.other_child VALUES(1)" ] do
                      Expect.isNone (run sql |> errorInfo) sql
                  if checkpoint then snapshotNow directory store
                  let recovered = load directory
                  attach directory recovered
                  session <- Fsdb.Session.create 2 recovered
                  for sql in [ "ALTER TABLE parent RENAME COLUMN n TO id"; "ALTER TABLE child RENAME COLUMN a TO parent_id" ] do
                      Expect.isNone (run sql |> errorInfo) sql
                  let verify (store: Store) =
                      session <- Fsdb.Session.create 3 store
                      let foreignKey = store.Catalog.[defaultDatabase].["child"].ForeignKeys.Head
                      Expect.equal foreignKey.Columns [ "parent_id" ] "child column is retargeted"
                      Expect.equal foreignKey.RefColumns [ "id" ] "parent column is retargeted"
                      Expect.equal store.Catalog.["related"].["other_child"].ForeignKeys.Head.RefColumns [ "id" ] "cross-schema reference is retargeted"
                      for sql in [ "INSERT INTO child VALUES(2)"; "INSERT INTO related.other_child VALUES(2)" ] do
                          Expect.equal (run sql |> errorInfo |> Option.map _.Code) (Some 1452) sql
                      Expect.equal (run "UPDATE parent SET id=2 WHERE id=1" |> errorInfo |> Option.map _.Code) (Some 1451) "parent remains protected"
                  verify recovered
                  verify (load directory)
                  snapshotNow directory recovered
                  verify (load directory)

          testCase "foreign-key rename collisions and names survive recovery"
          <| fun _ ->
              for checkpoint in [ false; true ] do
                  let directory = tempDataDir()
                  let store = load directory
                  attach directory store
                  let mutable session = Fsdb.Session.create 1 store
                  let run sql =
                      let next, result = handle session sql
                      session <- next
                      result
                  for sql in
                      [ "CREATE TABLE parent(n INT PRIMARY KEY)"
                        "CREATE TABLE child(a INT,FOREIGN KEY(a) REFERENCES parent(n))"
                        "CREATE TABLE other(a INT,CONSTRAINT renamed_ibfk_1 FOREIGN KEY(a) REFERENCES parent(n))" ] do
                      Expect.isNone (run sql |> errorInfo) sql
                  if checkpoint then snapshotNow directory store
                  let recovered = load directory
                  attach directory recovered
                  session <- Fsdb.Session.create 2 recovered
                  Expect.equal
                      (run "RENAME TABLE parent TO parent_new,child TO renamed" |> errorInfo |> Option.map _.Code)
                      (Some 1826) "failed batch is rejected after recovery"
                  let unchanged = (load directory).Catalog.[defaultDatabase]
                  Expect.isTrue (unchanged.ContainsKey "parent" && unchanged.ContainsKey "child") "failed batch leaves original names on disk"
                  Expect.isFalse (unchanged.ContainsKey "parent_new" || unchanged.ContainsKey "renamed") "failed batch is not journaled"
                  Expect.isNone (run "ALTER TABLE child RENAME TO valid" |> errorInfo) "noncolliding rename succeeds"
                  let verify (store: Store) =
                      let database = store.Catalog.[defaultDatabase]
                      Expect.isFalse (database.ContainsKey "child") "old table name is gone"
                      Expect.equal (database.["valid"].ForeignKeys |> List.map _.Name) [ "valid_ibfk_1" ] "renamed constraint survives"
                  verify recovered
                  verify (load directory)
                  snapshotNow directory recovered
                  verify (load directory)

          testCase "generated index provenance survives WAL and snapshots"
          <| fun _ ->
              for checkpoint in [ false; true ] do
                  let directory = tempDataDir()
                  let store = load directory
                  attach directory store
                  let mutable session = Fsdb.Session.create 1 store
                  let execute sql =
                      let next, result = handle session sql
                      session <- next
                      Expect.isNone (errorInfo result) sql
                  for sql in
                      [ "CREATE TABLE parent(n INT PRIMARY KEY)"
                        "CREATE TABLE child(a INT,b INT,CONSTRAINT fk FOREIGN KEY(a) REFERENCES parent(n))"
                        "CREATE TABLE explicit_child(a INT,b INT,KEY fk(a),CONSTRAINT explicit_fk FOREIGN KEY(a) REFERENCES parent(n))"
                        "CREATE TABLE renamed_child LIKE child"
                        "ALTER TABLE renamed_child RENAME INDEX fk TO renamed"
                        "CREATE TABLE copied_child LIKE child"
                        "CREATE TABLE same_name LIKE child" ] do execute sql
                  if checkpoint then snapshotNow directory store
                  let recovered = load directory
                  attach directory recovered
                  session <- Fsdb.Session.create 2 recovered
                  for table in [ "child"; "explicit_child"; "renamed_child"; "copied_child" ] do
                      execute ("ALTER TABLE " + table + " ADD INDEX replacement(a,b)")
                  execute "ALTER TABLE same_name ADD INDEX fk(a,b)"
                  let verify (store: Store) =
                      let indexes table = store.Catalog.[defaultDatabase].[table].Indexes |> List.map _.Name
                      Expect.equal (indexes "same_name") [ "fk" ] "same-name replacement is journaled once"
                      Expect.equal store.Catalog.[defaultDatabase].["same_name"].Indexes.Head.Columns [ "a"; "b" ] "replacement definition survives"
                      Expect.equal (indexes "child") [ "replacement" ] "generated index is replaced"
                      Expect.equal (indexes "copied_child") [ "replacement" ] "LIKE preserves origin"
                      Expect.equal (indexes "explicit_child") [ "fk"; "replacement" ] "explicit index is retained"
                      Expect.equal (indexes "renamed_child") [ "renamed"; "replacement" ] "renamed index is retained"
                  verify recovered
                  verify (load directory)
                  snapshotNow directory recovered
                  verify (load directory)

          testCase "index provenance defaults conservatively for format 22 recovery"
          <| fun _ ->
              let snapshot = Convert.FromBase64String ""
              let wal = Convert.FromBase64String "UgAAAIDsVk4FAQAAACgEZnNkYgMNbGVnYWN5X29yaWdpbgEAAAABYQQAAQAAAAAAAAAAAAABAAAAAmZrAQAAAAQATjphAAEAAAAAAAAAAAAAANwAWTfpJd8I"
              for snapshotBytes, walBytes in [ snapshot, [||]; [||], wal ] do
                  let directory = tempDataDir()
                  if snapshotBytes.Length > 0 then File.WriteAllBytes(snapshotPath directory, snapshotBytes)
                  if walBytes.Length > 0 then File.WriteAllBytes(walPath directory, walBytes)
                  let recovered = load directory
                  let index = recovered.Catalog.[defaultDatabase].["legacy_origin"].Indexes |> List.exactlyOne
                  Expect.isFalse index.GeneratedForForeignKey "older formats do not prove generated origin"
                  let session = Fsdb.Session.create 1 recovered
                  let _, result = handle session "ALTER TABLE legacy_origin ADD INDEX replacement(a)"
                  Expect.isNone (errorInfo result) "legacy ALTER succeeds"
                  Expect.equal recovered.Catalog.[defaultDatabase].["legacy_origin"].Indexes.Length 2 "unknown origin is retained"

          testCase "durability selects OS-supported flush and shutdown paths"
          <| fun _ ->
              Expect.equal (durableFlushMethod true) ManagedFlush "Windows uses the managed durable flush"
              Expect.equal (durableFlushMethod false) PosixFsync "Unix uses plain fsync"

              Expect.equal
                  (shutdownSignals true)
                  [ Runtime.InteropServices.PosixSignal.SIGINT ]
                  "Windows registers only its supported console signal"

              Expect.equal
                  (shutdownSignals false)
                  [ Runtime.InteropServices.PosixSignal.SIGTERM; Runtime.InteropServices.PosixSignal.SIGINT ]
                  "Unix registers termination and interrupt signals"

          testList
              "group commit queue"
              [ testCase "writes arriving during a flush share the next batch"
                <| fun _ ->
                    let batches = ResizeArray<int list>()
                    use flushStarted = new Threading.ManualResetEventSlim()
                    use releaseFlush = new Threading.ManualResetEventSlim()

                    let queue =
                        Fsdb.GroupCommit.Queue<int>(
                            8,
                            (fun batch ->
                                batches.Add batch

                                if batches.Count = 1 then
                                    flushStarted.Set()
                                    releaseFlush.Wait()),
                            ignore
                        )

                    let first = queue.Enqueue 1
                    let firstTask = Threading.Tasks.Task.Run first
                    Expect.isTrue (flushStarted.Wait(TimeSpan.FromSeconds 5.)) "the first flush starts"

                    let second = queue.Enqueue 2
                    let third = queue.Enqueue 3
                    let secondTask = Threading.Tasks.Task.Run second
                    let thirdTask = Threading.Tasks.Task.Run third
                    releaseFlush.Set()
                    Threading.Tasks.Task.WaitAll [| firstTask; secondTask; thirdTask |]

                    Expect.sequenceEqual batches [ [ 1 ]; [ 2; 3 ] ] "followers share one ordered flush"

                testCase "checkpoints split adjacent write batches without reordering"
                <| fun _ ->
                    let operations = ResizeArray<string>()

                    let queue =
                        Fsdb.GroupCommit.Queue<int>(
                            8,
                            (fun batch -> operations.Add(sprintf "write:%A" batch)),
                            (fun () -> operations.Add "checkpoint")
                        )

                    let first = queue.Enqueue 1
                    let checkpoint = queue.EnqueueCheckpoint()
                    let second = queue.Enqueue 2
                    first ()
                    checkpoint ()
                    second ()

                    Expect.sequenceEqual operations [ "write:[1]"; "checkpoint"; "write:[2]" ] "barrier order"

                testCase "a flush failure reaches every waiter and closes the queue"
                <| fun _ ->
                    let queue = Fsdb.GroupCommit.Queue<int>(8, (fun _ -> invalidOp "disk failed"), ignore)
                    let first = queue.Enqueue 1
                    let second = queue.Enqueue 2

                    Expect.throwsT<InvalidOperationException> first "the leader sees the flush failure"
                    Expect.throwsT<InvalidOperationException> second "the follower sees the same flush failure"

                    Expect.throwsT<InvalidOperationException>
                        (fun () -> queue.Enqueue 3 |> ignore)
                        "a failed queue refuses later writes"

                testCase "capacity applies backpressure until the leader drains"
                <| fun _ ->
                    let batches = ResizeArray<int list>()
                    let queue = Fsdb.GroupCommit.Queue<int>(1, batches.Add, ignore)
                    let first = queue.Enqueue 1
                    let follower =
                        Threading.Tasks.Task.Run<unit -> unit>(System.Func<unit -> unit>(fun () -> queue.Enqueue 2))
                    Expect.isFalse (follower.Wait(TimeSpan.FromMilliseconds 100.)) "a full queue blocks another producer"
                    first ()
                    Expect.isTrue (follower.Wait(TimeSpan.FromSeconds 5.)) "draining releases the producer"
                    follower.Result ()
                    Expect.sequenceEqual batches [ [ 1 ]; [ 2 ] ] "both writes retain order"

                testCase "concurrent producers: every acked write lands in exactly one batch, in per-producer order"
                <| fun _ ->
                    // Flush callbacks are serialized, so `batches` is confined
                    // to the active queue leader while producers race for it.
                    let batches = ResizeArray<int list>()
                    let queue = Fsdb.GroupCommit.Queue<int>(4, batches.Add, ignore)
                    let producers = 8
                    let perProducer = 50

                    let tasks =
                        [| for p in 0 .. producers - 1 ->
                               Threading.Tasks.Task.Run(fun () ->
                                   for i in 0 .. perProducer - 1 do
                                       queue.Enqueue(p * perProducer + i) ()) |]

                    Expect.isTrue
                        (Threading.Tasks.Task.WaitAll(tasks, TimeSpan.FromSeconds 30.))
                        "all producers drain without wedging"

                    let flushed = batches |> List.concat
                    Expect.equal (List.length flushed) (producers * perProducer) "every acked write flushed exactly once"
                    Expect.equal (List.sort flushed) [ 0 .. producers * perProducer - 1 ] "no write lost or duplicated"

                    for p in 0 .. producers - 1 do
                        let mine = flushed |> List.filter (fun v -> v / perProducer = p)

                        Expect.equal
                            mine
                            [ p * perProducer .. (p + 1) * perProducer - 1 ]
                            (sprintf "producer %d's writes flush in the order it acked them" p) ]

          testCase "grouped USING views retain logical columns after recovery"
          <| fun _ ->
              for checkpoint in [ false; true ] do
                  let directory = tempDataDir ()
                  let store = load directory
                  attach directory store
                  let session = Fsdb.Session.create 1 store
                  for sql in
                      [ "CREATE TABLE a(id INT)"; "CREATE TABLE b(id INT)"; "CREATE TABLE c(id INT)"
                        "INSERT INTO a VALUES(1),(2)"; "INSERT INTO b VALUES(1),(3)"; "INSERT INTO c VALUES(3)"
                        "CREATE VIEW grouped_view(aid,shared_id) AS SELECT * FROM a LEFT JOIN (b LEFT JOIN c USING(id)) ON a.id=b.id" ] do
                      match handle session sql |> snd with
                      | Err(code, message) -> failtestf "%d %s" code message
                      | _ -> ()
                  if checkpoint then snapshotNow directory store
                  let recovered = Fsdb.Session.create 2 (load directory)
                  Expect.equal (handle recovered "SELECT * FROM grouped_view ORDER BY aid" |> snd)
                      (ResultSet([ "aid"; "shared_id" ], [ [ Some "1"; Some "1" ]; [ Some "2"; None ] ]))
                      "WAL and snapshot recovery preserve grouped column ownership"

          testCase "attach + reload round-trips one value of every Value case, including datetime fractional seconds"
          <| fun _ ->
              let dir = tempDataDir ()
              let store = load dir
              attach dir store
              createTable store defaultDatabase "vals" usersColumns [] [] None None |> ignore

              insertRows store defaultDatabase "vals" None [ [ VNull; VString "row1"; VNull ] ] |> ignore

              insertRows
                  store
                  defaultDatabase
                  "vals"
                  None
                  [ [ VInt 42L; VString "unicode héllo 🎉"; VJson """{"a":1}""" ] ]
              |> ignore

              let reloaded = load dir
              let rows = rowsOf reloaded defaultDatabase "vals"
              Expect.equal (List.length rows) 2 "both inserted rows survive"
              Expect.contains rows [| VInt 1L; VString "row1"; VNull |] "NULL round-trips"
              // `note` is a `TText` column — `Storage.coerceValue` coerces
              // any value written to it down to `VString` at insert time
              // (true for `VJson` too), so that's the physical value the WAL
              // actually carries and replay should reproduce.
              Expect.contains rows [| VInt 42L; VString "unicode héllo 🎉"; VString """{"a":1}""" |] "unicode/JSON-text round-trip"

          testCase "WAL and snapshot recovery retain spatial column metadata"
          <| fun _ ->
              let dir = tempDataDir ()
              let store = load dir
              attach dir store
              let column = { mkCol "shape" (TGeometry Point) with Nullable = false; Srid = Some 0u }
              let index = { Name = "sx"; GeneratedForForeignKey = false; KeyColumns = indexColumns [ "shape" ]; Unique = false; Visible = true; Kind = SpatialIndex }
              createTable store defaultDatabase "places" [ column ] [ index ] [] None None |> ignore
              let point = VGeometry(tryGeometryFromText 0 "POINT(1.5 -2)" |> Option.get)
              insertRows store defaultDatabase "places" None [ [ point ] ] |> ignore

              let reloaded = load dir
              Expect.equal (rowsOf reloaded defaultDatabase "places") [ [| point |] ] "geometry row survives WAL replay"
              let reloadedTable = reloaded.Catalog.[defaultDatabase].["places"]
              Expect.equal reloadedTable.Columns.Head.Srid (Some 0u) "WAL column SRID"
              Expect.equal reloadedTable.Indexes.Head.Kind SpatialIndex "WAL index kind"

              match
                  trySpatialLookup
                      reloaded
                      defaultDatabase
                      "places"
                      "shape"
                      Fsdb.SpatialIndex.Intersects
                      (tryGeometryFromText 0 "POINT(1.5 -2)" |> Option.get)
              with
              | Some lookup -> Expect.equal lookup.SpatialRows.Length 1 "WAL spatial entries"
              | None -> failtest "expected the WAL spatial index"

              snapshotNow dir store
              let snapshotted = load dir
              let snapshottedTable = snapshotted.Catalog.[defaultDatabase].["places"]
              Expect.equal snapshottedTable.Columns.Head.Srid (Some 0u) "snapshot column SRID"
              Expect.equal snapshottedTable.Indexes.Head.Kind SpatialIndex "snapshot index kind"

              match
                  trySpatialLookup
                      snapshotted
                      defaultDatabase
                      "places"
                      "shape"
                      Fsdb.SpatialIndex.Intersects
                      (tryGeometryFromText 0 "POINT(1.5 -2)" |> Option.get)
              with
              | Some lookup -> Expect.equal lookup.SpatialRows.Length 1 "snapshot spatial entries"
              | None -> failtest "expected the snapshot spatial index"

          testCase "WAL and snapshot recovery retain typed TIME values"
          <| fun _ ->
              let dir = tempDataDir ()
              let store = load dir
              attach dir store
              createTable store defaultDatabase "times" [ mkCol "value" (TTime 6) ] [] [] None None |> ignore
              let value = tryParseTimeValue "-838:59:58.123456" |> Option.get |> VTime
              insertRows store defaultDatabase "times" None [ [ value ] ] |> ignore

              Expect.equal (rowsOf (load dir) defaultDatabase "times") [ [| value |] ] "WAL replay"

              snapshotNow dir store
              Expect.equal (rowsOf (load dir) defaultDatabase "times") [ [| value |] ] "snapshot replay"

          testCase "WAL and snapshot recovery retain TIMESTAMP instants"
          <| fun _ ->
              let dir = tempDataDir ()
              let store = load dir
              attach dir store
              let session = Fsdb.Session.create 1 store
              let session, _ = handle session "CREATE TABLE timestamp_zones (stamp TIMESTAMP(6))"
              let session, _ = handle session "SET time_zone = '+05:30'"
              let _, result = handle session "INSERT INTO timestamp_zones VALUES ('2024-01-01 00:00:00.123456')"
              Expect.equal result (Affected 1UL) "insert timestamp"

              let expected = VTimestamp(DateTime(2023, 12, 31, 18, 30, 0, 123, DateTimeKind.Utc).AddTicks(4560L))
              Expect.equal (rowsOf (load dir) defaultDatabase "timestamp_zones") [ [| expected |] ] "WAL preserves the UTC instant"

              snapshotNow dir store
              let reloaded = load dir
