                            "GRANT BACKUP_ADMIN ON *.* TO `worker`@`%` WITH GRANT OPTION"
                            "GRANT SELECT, INSERT ON `shop`.* TO `worker`@`%`"
                            "GRANT DELETE, SELECT (`id`) ON `shop`.`orders` TO `worker`@`%`" ]
                          (label + " grants minus the revoked UPDATE")
