              // recursion (`row :: applyRowChanges ...`) overflows the stack
              // on restart. The 10,000-row event here sits past the ~3800
              // rows a non-tail recursion crashes at.
              let dir = tempDataDir ()
              let store = load dir
              attach dir store

              createTable
                  store
                  defaultDatabase
                  "bulk"
                  [ { Name = "id"
                      Type = TInt false
                      NumericDisplay = None
                      Nullable = false
                      Default = None
                      AutoIncrement = false
                      PrimaryKey = true
                      Unique = false
                      Generated = None
                      Comment = ""
                      Collation = None
                      Charset = None
                      ExpressionCollation = None
                      Srid = None
                      OnUpdateCurrentTimestamp = false }
                    { Name = "n"
                      Type = TInt false
                      NumericDisplay = None
                      Nullable = false
                      Default = None
                      AutoIncrement = false
                      PrimaryKey = false
                      Unique = false
                      Generated = None
                      Comment = ""
                      Collation = None
                      Charset = None
                      ExpressionCollation = None
                      Srid = None
                      OnUpdateCurrentTimestamp = false } ]
                  []
                  []
                  None
                  None
              |> ignore

              let rowCount = 10_000
              insertRows store defaultDatabase "bulk" None [ for i in 1 .. rowCount -> [ VInt(int64 i); VInt 0L ] ]
              |> ignore

              // One bulk UPDATE touching every row, as a single `RowsUpdated` event.
              updateRows store defaultDatabase "bulk" None (fun _ -> Ok true) (fun row ->
                  Ok [| row.[0]; VInt((row.[1] |> function VInt i -> i | _ -> 0L) + 1L) |])
              |> ignore

