                      let bodyIndex = table.Indexes |> List.find (fun index -> index.Name = "ix_body")
                      Expect.equal bodyIndex.KeyColumns [ { Name = "body"; PrefixLength = Some 12; Transform = None; Direction = Desc } ] "key-part attributes survive recovery"
